import{_ as i,C as n,c as o,o as s,a6 as a,G as l}from"./chunks/framework.BY05barL.js";const r="/ucasal-ssoo-estudio/assets/10-memoria-segmentada.CwnJSPzy.png",d="/ucasal-ssoo-estudio/assets/10-memoria-segmentada-2.Crg4CgkB.png",f=JSON.parse('{"title":"Segmentación","description":"","frontmatter":{},"headers":[],"relativePath":"unidad3/segmentacion.md","filePath":"unidad3/segmentacion.md"}'),c={name:"unidad3/segmentacion.md"};function m(g,e,p,u,h,b){const t=n("SegmentTranslationSimulator");return s(),o("div",null,[e[0]||(e[0]=a('<h1 id="segmentacion" tabindex="-1">Segmentación <a class="header-anchor" href="#segmentacion" aria-label="Permalink to &quot;Segmentación&quot;">​</a></h1><p>La <strong>segmentación</strong> es una técnica de gestión de memoria que divide el espacio de direcciones de un proceso en segmentos lógicos de tamaño variable, cada uno representando una unidad lógica del programa.</p><h2 id="conceptos-clave" tabindex="-1">Conceptos Clave <a class="header-anchor" href="#conceptos-clave" aria-label="Permalink to &quot;Conceptos Clave&quot;">​</a></h2><h3 id="¿que-es-un-segmento" tabindex="-1">¿Qué es un Segmento? <a class="header-anchor" href="#¿que-es-un-segmento" aria-label="Permalink to &quot;¿Qué es un Segmento?&quot;">​</a></h3><p>Un segmento es una unidad lógica del programa:</p><ul><li><strong>Código</strong> (text segment)</li><li><strong>Datos globales</strong> (data segment)</li><li><strong>Pila</strong> (stack segment)</li><li><strong>Heap</strong> (heap segment)</li><li><strong>Bibliotecas compartidas</strong></li></ul><p>A diferencia de la paginación (bloques de tamaño fijo), los segmentos tienen <strong>tamaño variable</strong> según las necesidades lógicas del programa.</p><h2 id="memoria-segmentada" tabindex="-1">Memoria Segmentada <a class="header-anchor" href="#memoria-segmentada" aria-label="Permalink to &quot;Memoria Segmentada&quot;">​</a></h2><p><img src="'+r+'" alt="Memoria Segmentada"></p><h3 id="direccion-virtual-en-segmentacion" tabindex="-1">Dirección Virtual en Segmentación <a class="header-anchor" href="#direccion-virtual-en-segmentacion" aria-label="Permalink to &quot;Dirección Virtual en Segmentación&quot;">​</a></h3><p>Una dirección virtual se compone de dos partes:</p><ul><li><strong>Número de segmento (s)</strong>: Identifica el segmento</li><li><strong>Desplazamiento (d)</strong>: Posición dentro del segmento</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Dirección Virtual = (s, d)</span></span></code></pre></div><h2 id="tabla-de-segmentos" tabindex="-1">Tabla de Segmentos <a class="header-anchor" href="#tabla-de-segmentos" aria-label="Permalink to &quot;Tabla de Segmentos&quot;">​</a></h2><p>Cada proceso tiene una <strong>tabla de segmentos</strong> que mapea segmentos virtuales a direcciones físicas.</p><p><img src="'+d+`" alt="Tabla de Segmentos"></p><h3 id="campos-de-la-tabla-de-segmentos" tabindex="-1">Campos de la Tabla de Segmentos <a class="header-anchor" href="#campos-de-la-tabla-de-segmentos" aria-label="Permalink to &quot;Campos de la Tabla de Segmentos&quot;">​</a></h3><p>Cada entrada contiene:</p><table tabindex="0"><thead><tr><th>Campo</th><th>Descripción</th></tr></thead><tbody><tr><td><strong>Base</strong></td><td>Dirección física inicial del segmento en memoria</td></tr><tr><td><strong>Límite</strong></td><td>Tamaño del segmento (longitud)</td></tr><tr><td><strong>Permisos</strong></td><td>Lectura (R), Escritura (W), Ejecución (X)</td></tr><tr><td><strong>Validez</strong></td><td>Bit que indica si el segmento está en memoria</td></tr></tbody></table><h3 id="traduccion-de-direcciones" tabindex="-1">Traducción de Direcciones <a class="header-anchor" href="#traduccion-de-direcciones" aria-label="Permalink to &quot;Traducción de Direcciones&quot;">​</a></h3><p><strong>Algoritmo:</strong></p><ol><li>Extraer número de segmento (s) y desplazamiento (d) de la dirección virtual</li><li>Verificar que s sea válido (s &lt; número de segmentos)</li><li>Buscar entrada s en la tabla de segmentos</li><li>Verificar que d &lt; Límite (protección)</li><li>Calcular dirección física: <strong>Base[s] + d</strong></li></ol><p><strong>Ejemplo:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Dirección Virtual: (2, 400)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Tabla de segmentos:</span></span>
<span class="line"><span>Segmento 2: Base = 1700, Límite = 700</span></span>
<span class="line"><span></span></span>
<span class="line"><span>¿Es válido? d (400) &lt; Límite (700) ✓</span></span>
<span class="line"><span>Dirección Física = 1700 + 400 = 2100</span></span></code></pre></div><h2 id="ejercicio-9-paginacion-y-segmentacion" tabindex="-1">Ejercicio 9: Paginación y Segmentación <a class="header-anchor" href="#ejercicio-9-paginacion-y-segmentacion" aria-label="Permalink to &quot;Ejercicio 9: Paginación y Segmentación&quot;">​</a></h2><ul><li>Sistema de 16 bits</li><li>Páginas de 4 KB</li><li>Código: 31945 bytes</li><li>Datos: 15386 bytes</li><li>Pila: 16870 bytes</li></ul><p>a) ¿Se puede ejecutar el programa?</p><ul><li>Sistema de 16 bits → 2^16 = 65536 bytes (64 KB) de espacio de direcciones</li><li>Tamaño de página = 4 KB = 4096 bytes</li><li>Número de páginas = 65536 / 4096 = 16 páginas</li><li>Tamaño total del programa = 31945 + 15386 + 16870 = 64201 bytes (entraría en 65536, pero cada segmento ocupa páginas enteras) <ul><li>El código ocupa 8 páginas (31945 / 4096 ≈ 7.8 → 8)</li><li>Los datos ocupan 4 páginas (15386 / 4096 ≈ 3.76 → 4)</li><li>La pila ocupa 5 páginas (16870 / 4096 ≈ 4.12 → 5)</li><li>Total páginas necesarias = 8 + 4 + 5 = 17 páginas</li></ul></li><li><strong>No se puede ejecutar el programa</strong> porque se necesitan 17 páginas y solo hay 16 disponibles.</li></ul><p>b) ¿Si el tamaño de la página es de 256 bytes en lugar de 4Kb se puede ejecutar el programa? Considere que se puede asignar todo el direccionamiento de 16 bits al proceso y que una página no puede contener datos de diferentes segmentos.</p><ul><li>Tamaño de página = 256 bytes</li><li>Número de páginas = 65536 / 256 = 256 páginas</li><li>Tamaño total del programa = 64201 bytes <ul><li>El código ocupa 125 páginas (31945 / 256 ≈ 124.8 → 125)</li><li>Los datos ocupan 61 páginas (15386 / 256 ≈ 60.1 → 61)</li><li>La pila ocupa 66 páginas (16870 / 256 ≈ 65.9 → 66)</li><li>Total páginas necesarias = 125 + 61 + 66 = 252 páginas</li></ul></li><li><strong>Sí se puede ejecutar el programa</strong> porque se necesitan 252 páginas y hay 256 disponibles.</li></ul><h2 id="ejercicio-10-traduccion-de-direcciones-con-segmentacion" tabindex="-1">Ejercicio 10: Traducción de Direcciones con Segmentación <a class="header-anchor" href="#ejercicio-10-traduccion-de-direcciones-con-segmentacion" aria-label="Permalink to &quot;Ejercicio 10: Traducción de Direcciones con Segmentación&quot;">​</a></h2><p>Dada la siguiente tabla de segmentos:</p><table tabindex="0"><thead><tr><th>Segmento</th><th>Base</th><th>Longitud</th></tr></thead><tbody><tr><td>0</td><td>23</td><td>310</td></tr><tr><td>1</td><td>350</td><td>600</td></tr><tr><td>2</td><td>1700</td><td>700</td></tr><tr><td>3</td><td>2700</td><td>68</td></tr><tr><td>4</td><td>950</td><td>450</td></tr></tbody></table><p>Traducir las siguientes direcciones virtuales:</p><h3 id="a-0-230" tabindex="-1">a) (0, 230) <a class="header-anchor" href="#a-0-230" aria-label="Permalink to &quot;a) (0, 230)&quot;">​</a></h3><ul><li>Segmento 0: Base = 23, Límite = 310</li><li>¿230 &lt; 310? ✓</li><li><strong>Dirección física = 23 + 230 = 253</strong></li></ul><h3 id="b-1-2" tabindex="-1">b) (1, 2) <a class="header-anchor" href="#b-1-2" aria-label="Permalink to &quot;b) (1, 2)&quot;">​</a></h3><ul><li>Segmento 1: Base = 350, Límite = 600</li><li>¿2 &lt; 600? ✓</li><li><strong>Dirección física = 350 + 2 = 352</strong></li></ul><h3 id="c-1-602" tabindex="-1">c) (1, 602) <a class="header-anchor" href="#c-1-602" aria-label="Permalink to &quot;c) (1, 602)&quot;">​</a></h3><ul><li>Segmento 1: Base = 350, Límite = 600</li><li>¿602 &lt; 600? ✗</li><li><strong>Error: Violación de segmento (Segmentation Fault)</strong></li><li>El desplazamiento excede el límite del segmento</li></ul><h3 id="d-2-699" tabindex="-1">d) (2, 699) <a class="header-anchor" href="#d-2-699" aria-label="Permalink to &quot;d) (2, 699)&quot;">​</a></h3><ul><li>Segmento 2: Base = 1700, Límite = 700</li><li>¿699 &lt; 700? ✓</li><li><strong>Dirección física = 1700 + 699 = 2399</strong></li></ul><h3 id="e-3-400" tabindex="-1">e) (3, 400) <a class="header-anchor" href="#e-3-400" aria-label="Permalink to &quot;e) (3, 400)&quot;">​</a></h3><ul><li>Segmento 3: Base = 2700, Límite = 68</li><li>¿400 &lt; 68? ✗</li><li><strong>Error: Violación de segmento</strong></li><li>El desplazamiento es mucho mayor que el tamaño del segmento</li></ul><h3 id="f-4-700" tabindex="-1">f) (4, 700) <a class="header-anchor" href="#f-4-700" aria-label="Permalink to &quot;f) (4, 700)&quot;">​</a></h3><ul><li>Segmento 4: Base = 950, Límite = 450</li><li>¿700 &lt; 450? ✗</li><li><strong>Error: Violación de segmento</strong></li></ul><h3 id="simulador" tabindex="-1">Simulador <a class="header-anchor" href="#simulador" aria-label="Permalink to &quot;Simulador&quot;">​</a></h3><p>Tocá una dirección (o escribí otra) para ver la verificación y dónde cae en memoria.</p>`,48)),l(t),e[1]||(e[1]=a(`<h2 id="ventajas-de-la-segmentacion" tabindex="-1">Ventajas de la Segmentación <a class="header-anchor" href="#ventajas-de-la-segmentacion" aria-label="Permalink to &quot;Ventajas de la Segmentación&quot;">​</a></h2><h3 id="_1-refleja-la-estructura-logica-del-programa" tabindex="-1">1. <strong>Refleja la estructura lógica del programa</strong> <a class="header-anchor" href="#_1-refleja-la-estructura-logica-del-programa" aria-label="Permalink to &quot;1. **Refleja la estructura lógica del programa**&quot;">​</a></h3><ul><li>Los segmentos corresponden a unidades lógicas (código, datos, pila)</li><li>Facilita la programación y organización</li></ul><h3 id="_2-facilita-el-compartimiento" tabindex="-1">2. <strong>Facilita el compartimiento</strong> <a class="header-anchor" href="#_2-facilita-el-compartimiento" aria-label="Permalink to &quot;2. **Facilita el compartimiento**&quot;">​</a></h3><ul><li>Varios procesos pueden compartir el mismo segmento de código</li><li>Ejemplo: bibliotecas compartidas (libc, libm)</li></ul><h3 id="_3-proteccion-natural" tabindex="-1">3. <strong>Protección natural</strong> <a class="header-anchor" href="#_3-proteccion-natural" aria-label="Permalink to &quot;3. **Protección natural**&quot;">​</a></h3><ul><li>Permisos por segmento: código ejecutable pero no escribible</li><li>Datos escribibles pero no ejecutables</li><li>Un segmento de datos no ejecutable mitiga la inyección de código (por ejemplo, vía buffer overflow), aunque no evita el desbordamiento en sí</li></ul><h3 id="_4-crecimiento-dinamico" tabindex="-1">4. <strong>Crecimiento dinámico</strong> <a class="header-anchor" href="#_4-crecimiento-dinamico" aria-label="Permalink to &quot;4. **Crecimiento dinámico**&quot;">​</a></h3><ul><li>Segmentos como heap y stack pueden crecer dinámicamente</li><li>Cada segmento ocupa lo que necesita, sin fragmentación interna (a cambio, sufre fragmentación externa; ver desventajas)</li></ul><h3 id="_5-facilita-la-compilacion-y-enlace" tabindex="-1">5. <strong>Facilita la compilación y enlace</strong> <a class="header-anchor" href="#_5-facilita-la-compilacion-y-enlace" aria-label="Permalink to &quot;5. **Facilita la compilación y enlace**&quot;">​</a></h3><ul><li>Módulos se compilan como segmentos separados</li><li>Enlace dinámico más sencillo</li></ul><h2 id="desventajas-de-la-segmentacion" tabindex="-1">Desventajas de la Segmentación <a class="header-anchor" href="#desventajas-de-la-segmentacion" aria-label="Permalink to &quot;Desventajas de la Segmentación&quot;">​</a></h2><h3 id="_1-fragmentacion-externa" tabindex="-1">1. <strong>Fragmentación externa</strong> <a class="header-anchor" href="#_1-fragmentacion-externa" aria-label="Permalink to &quot;1. **Fragmentación externa**&quot;">​</a></h3><ul><li>Segmentos de tamaño variable → huecos entre segmentos (<em>checkerboarding</em>, efecto tablero de ajedrez)</li><li>Requiere compactación periódica (costosa)</li></ul><h3 id="_2-complejidad-en-asignacion" tabindex="-1">2. <strong>Complejidad en asignación</strong> <a class="header-anchor" href="#_2-complejidad-en-asignacion" aria-label="Permalink to &quot;2. **Complejidad en asignación**&quot;">​</a></h3><ul><li>¿Dónde ubicar un segmento de tamaño variable?</li><li>Algoritmos: First-Fit, Best-Fit, Worst-Fit</li></ul><h3 id="_3-limite-en-el-tamano-de-segmentos" tabindex="-1">3. <strong>Límite en el tamaño de segmentos</strong> <a class="header-anchor" href="#_3-limite-en-el-tamano-de-segmentos" aria-label="Permalink to &quot;3. **Límite en el tamaño de segmentos**&quot;">​</a></h3><ul><li>Un segmento debe caber completo en memoria</li><li>Segmentos muy grandes pueden no caber</li></ul><h3 id="_4-tabla-de-segmentos-mas-compleja" tabindex="-1">4. <strong>Tabla de segmentos más compleja</strong> <a class="header-anchor" href="#_4-tabla-de-segmentos-mas-compleja" aria-label="Permalink to &quot;4. **Tabla de segmentos más compleja**&quot;">​</a></h3><ul><li>Cada entrada requiere más información (base + límite + permisos)</li></ul><h2 id="proteccion-y-compartimiento" tabindex="-1">Protección y Compartimiento <a class="header-anchor" href="#proteccion-y-compartimiento" aria-label="Permalink to &quot;Protección y Compartimiento&quot;">​</a></h2><h3 id="bits-de-proteccion" tabindex="-1">Bits de Protección <a class="header-anchor" href="#bits-de-proteccion" aria-label="Permalink to &quot;Bits de Protección&quot;">​</a></h3><p>Cada segmento tiene bits que indican operaciones permitidas:</p><table tabindex="0"><thead><tr><th>Bit</th><th>Permiso</th><th>Descripción</th></tr></thead><tbody><tr><td>R</td><td>Read</td><td>Permite lectura</td></tr><tr><td>W</td><td>Write</td><td>Permite escritura</td></tr><tr><td>X</td><td>Execute</td><td>Permite ejecución</td></tr></tbody></table><p><strong>Ejemplos típicos:</strong></p><ul><li>Segmento de código: R-X (lectura y ejecución, sin escritura)</li><li>Segmento de datos: RW- (lectura y escritura, sin ejecución)</li><li>Segmento de solo lectura: R-- (solo lectura)</li></ul><h3 id="compartimiento-de-segmentos" tabindex="-1">Compartimiento de Segmentos <a class="header-anchor" href="#compartimiento-de-segmentos" aria-label="Permalink to &quot;Compartimiento de Segmentos&quot;">​</a></h3><p>Múltiples procesos pueden compartir el mismo segmento físico:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Proceso A:</span></span>
<span class="line"><span>  Segmento 1 → Base = 5000 (código compartido)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Proceso B:</span></span>
<span class="line"><span>  Segmento 2 → Base = 5000 (mismo código)</span></span></code></pre></div><p><strong>Ventajas:</strong></p><ul><li>Ahorro de memoria</li><li>Consistencia de código</li><li>Bibliotecas compartidas</li></ul><h2 id="comparacion-segmentacion-vs-paginacion" tabindex="-1">Comparación: Segmentación vs Paginación <a class="header-anchor" href="#comparacion-segmentacion-vs-paginacion" aria-label="Permalink to &quot;Comparación: Segmentación vs Paginación&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Característica</th><th>Segmentación</th><th>Paginación</th></tr></thead><tbody><tr><td>Tamaño de unidades</td><td>Variable</td><td>Fijo</td></tr><tr><td>Visibilidad</td><td>Visible al programador</td><td>Transparente</td></tr><tr><td>Fragmentación</td><td>Externa</td><td>Interna</td></tr><tr><td>Compartimiento</td><td>Fácil y natural</td><td>Posible pero menos natural</td></tr><tr><td>Protección</td><td>Por segmento (granular)</td><td>Por página</td></tr><tr><td>Estructura lógica</td><td>Refleja programa</td><td>Artificial</td></tr><tr><td>Tabla por proceso</td><td>Pequeña (pocos segmentos)</td><td>Grande (muchas páginas)</td></tr></tbody></table>`,33))])}const P=i(c,[["render",m]]);export{f as __pageData,P as default};
